import{_ as d,o as e,c as r,ah as a}from"./chunks/framework.DjU4PSOm.js";const g=JSON.parse('{"title":"Zing 기능 명세서","description":"","frontmatter":{},"headers":[{"level":2,"title":"1. 화면 목록","slug":"_1-화면-목록","link":"#_1-화면-목록","children":[]},{"level":2,"title":"2. 데이터 모델 (테이블 스키마)","slug":"_2-데이터-모델-테이블-스키마","link":"#_2-데이터-모델-테이블-스키마","children":[{"level":3,"title":"users","slug":"users","link":"#users","children":[]},{"level":3,"title":"diaries","slug":"diaries","link":"#diaries","children":[]},{"level":3,"title":"RLS 정책 (2026-09-19)","slug":"rls-정책-2026-09-19","link":"#rls-정책-2026-09-19","children":[]},{"level":3,"title":"zings (매칭)","slug":"zings-매칭","link":"#zings-매칭","children":[]},{"level":3,"title":"prompts (글감, 도입 여부 미정)","slug":"prompts-글감-도입-여부-미정","link":"#prompts-글감-도입-여부-미정","children":[]},{"level":3,"title":"messages","slug":"messages","link":"#messages","children":[]}]},{"level":2,"title":"3. API 계약 (함수 시그니처)","slug":"_3-api-계약-함수-시그니처","link":"#_3-api-계약-함수-시그니처","children":[{"level":3,"title":"signUp 상세","slug":"signup-상세","link":"#signup-상세","children":[]},{"level":3,"title":"signIn 상세","slug":"signin-상세","link":"#signin-상세","children":[]}]},{"level":2,"title":"4. 정책/제약 규칙 (미정 항목 — 확정되면 여기 기록)","slug":"_4-정책-제약-규칙-미정-항목-—-확정되면-여기-기록","link":"#_4-정책-제약-규칙-미정-항목-—-확정되면-여기-기록","children":[]}],"relativePath":"computer/project/Zing/기능명세서.md","filePath":"computer/project/Zing/기능명세서.md"}'),o={name:"computer/project/Zing/기능명세서.md"};function i(l,t,c,n,s,h){return e(),r("div",null,[...t[0]||(t[0]=[a('<h1 id="zing-기능-명세서" tabindex="-1">Zing 기능 명세서 <a class="header-anchor" href="#zing-기능-명세서" aria-label="Permalink to &quot;Zing 기능 명세서&quot;">​</a></h1><p>병렬 작업(백엔드/프론트) 시 서로 안 부딪히기 위한 기준 문서. 항목이 바뀌면 여기부터 업데이트하고, 코드는 그 기준을 따라간다.</p><h2 id="_1-화면-목록" tabindex="-1">1. 화면 목록 <a class="header-anchor" href="#_1-화면-목록" aria-label="Permalink to &quot;1. 화면 목록&quot;">​</a></h2><table tabindex="0"><thead><tr><th>화면</th><th>설명</th><th>담당</th></tr></thead><tbody><tr><td>회원가입</td><td>계정 생성, 성별 비공개(자율 선택)</td><td>서희</td></tr><tr><td>로그인</td><td>이메일+비밀번호 로그인</td><td>서희</td></tr><tr><td>일기 작성</td><td>200~600자 검증</td><td>서희</td></tr><tr><td>피드</td><td>랜덤 일기 넘겨보기, 징 보내기</td><td>서희</td></tr><tr><td>매칭 목록</td><td>상호 징 성사된 상대 목록</td><td>서희</td></tr><tr><td>상대방 일기 상세</td><td>매칭된 상대 일기, 반응/댓글</td><td>서희</td></tr><tr><td>프로필</td><td>내 정보 관리</td><td>서희</td></tr><tr><td>채팅</td><td>제한적 소통 (로드맵 마지막 단계)</td><td>서희</td></tr><tr><td>알림</td><td>매칭 성사/반응 등 이벤트</td><td>서희</td></tr></tbody></table><p>(화면별 와이어프레임은 Figma 참고 — 링크 추가 예정)</p><h2 id="_2-데이터-모델-테이블-스키마" tabindex="-1">2. 데이터 모델 (테이블 스키마) <a class="header-anchor" href="#_2-데이터-모델-테이블-스키마" aria-label="Permalink to &quot;2. 데이터 모델 (테이블 스키마)&quot;">​</a></h2><blockquote><p>아래는 초안. 실제 Supabase 테이블 만들 때 이 표부터 채우고 시작.</p></blockquote><h3 id="users" tabindex="-1"><code>users</code> <a class="header-anchor" href="#users" aria-label="Permalink to &quot;`users`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>필드</th><th>타입</th><th>설명</th></tr></thead><tbody><tr><td>id</td><td>uuid</td><td>PK, <code>auth.users.id</code> 참조 FK (2026-09-19, 대시보드에서 수동 설정, ON DELETE CASCADE — Auth 계정 삭제 시 프로필도 자동 삭제됨)</td></tr><tr><td>nickname</td><td>text</td><td>화면에 보여줄 이름 (실명 아님)</td></tr><tr><td>gender</td><td>text | null</td><td><code>&#39;male&#39;</code> | <code>&#39;female&#39;</code> | <code>null</code>(비공개, 자율 선택)</td></tr><tr><td>is_exchange_student</td><td>boolean</td><td>교환학생 여부 — 매칭/번역 방향 결정에 필요</td></tr><tr><td>nationality</td><td>text</td><td>국적, 필수 — 매칭 상대의 문화적 배경을 아는 것이 서비스 핵심 가치라 비공개 옵션 없음(성별과 다름)</td></tr><tr><td>preferred_language</td><td>text</td><td>일기 작성/번역 기준 언어 (예: <code>&#39;ko&#39;</code>, <code>&#39;en&#39;</code>)</td></tr><tr><td>profile_image_url</td><td>text | null</td><td>프로필 이미지 (없으면 기본 이미지)</td></tr><tr><td>created_at</td><td>timestamp</td><td>가입일</td></tr></tbody></table><h3 id="diaries" tabindex="-1"><code>diaries</code> <a class="header-anchor" href="#diaries" aria-label="Permalink to &quot;`diaries`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>필드</th><th>타입</th><th>설명</th></tr></thead><tbody><tr><td>id</td><td>uuid</td><td>PK</td></tr><tr><td>author_id</td><td>uuid</td><td>FK → <code>users.id</code></td></tr><tr><td>content</td><td>text</td><td>200~600자 검증 (프론트+DB 양쪽에서 체크)</td></tr><tr><td>char_count</td><td>int</td><td><code>content</code> 글자 수 (검증/표시용으로 별도 저장)</td></tr><tr><td>created_at</td><td>timestamp</td><td>작성일</td></tr><tr><td>updated_at</td><td>timestamp | null</td><td>수정 시 갱신</td></tr></tbody></table><blockquote><p><strong>미정</strong>: &quot;매칭 전 절반만 공개&quot; 로직을 위한 필드는 아직 안 넣음 — 글자 수 기준인지 문단 기준인지(09-03 노트 미정 항목) 정해지면 그때 <code>public_preview</code> 같은 필드 또는 앱 로직(예: <code>content.slice(0, N)</code>)으로 처리할지 결정.</p></blockquote><h3 id="rls-정책-2026-09-19" tabindex="-1">RLS 정책 (2026-09-19) <a class="header-anchor" href="#rls-정책-2026-09-19" aria-label="Permalink to &quot;RLS 정책 (2026-09-19)&quot;">​</a></h3><p><code>users</code> 테이블 실제 동작 확인 중, <code>signUp</code> 테스트가 계속 403으로 막힌 문제를 디버깅해서 찾은 결론.</p><ul><li><code>Users can insert own profile</code> — INSERT, <code>to authenticated</code>, <code>with check (auth.uid() = id)</code></li><li><code>Users can view own profile</code> — SELECT, <code>to authenticated</code>, <code>using (auth.uid() = id)</code></li></ul><blockquote><p><strong>중요 교훈</strong>: <code>.insert(...).select()</code>처럼 insert 후 결과를 바로 조회하는 코드는 <strong>INSERT 정책뿐 아니라 SELECT 정책도 있어야</strong> 동작한다. SELECT 정책이 없으면 INSERT 자체는 성공해도, 결과를 돌려주는 단계(<code>RETURNING</code>)에서 막히면서 <strong>INSERT 정책 위반과 똑같은 403/RLS 에러 메시지</strong>가 떠서 원인 파악이 헷갈리기 쉽다. 앞으로 테이블 만들 때마다 CRUD로 실제 쓰는 동작(insert, select, update, delete) 각각에 맞는 정책을 다 챙겨야 함 — <code>diaries</code> 등 다른 테이블도 마찬가지로 필요.</p></blockquote><h3 id="zings-매칭" tabindex="-1"><code>zings</code> (매칭) <a class="header-anchor" href="#zings-매칭" aria-label="Permalink to &quot;`zings` (매칭)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>필드</th><th>타입</th><th>설명</th></tr></thead><tbody><tr><td>id</td><td>uuid</td><td></td></tr><tr><td>sender_id</td><td>uuid</td><td></td></tr><tr><td>receiver_id</td><td>uuid</td><td></td></tr><tr><td>matched_at</td><td>timestamp | null</td><td>상호 성사 시각</td></tr></tbody></table><h3 id="prompts-글감-도입-여부-미정" tabindex="-1"><code>prompts</code> (글감, 도입 여부 미정) <a class="header-anchor" href="#prompts-글감-도입-여부-미정" aria-label="Permalink to &quot;`prompts` (글감, 도입 여부 미정)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>필드</th><th>타입</th><th>설명</th></tr></thead></table><h3 id="messages" tabindex="-1"><code>messages</code> <a class="header-anchor" href="#messages" aria-label="Permalink to &quot;`messages`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>필드</th><th>타입</th><th>설명</th></tr></thead></table><h2 id="_3-api-계약-함수-시그니처" tabindex="-1">3. API 계약 (함수 시그니처) <a class="header-anchor" href="#_3-api-계약-함수-시그니처" aria-label="Permalink to &quot;3. API 계약 (함수 시그니처)&quot;">​</a></h2><blockquote><p>백엔드가 프론트에 제공하는 함수 목록. 이름/파라미터/리턴값을 여기서 먼저 정하고 나서 구현.</p></blockquote><table tabindex="0"><thead><tr><th>함수</th><th>파라미터</th><th>리턴</th><th>설명</th></tr></thead><tbody><tr><td><code>signUp</code></td><td><code>{ email, password, nickname, gender, isExchangeStudent, nationality, preferredLanguage }</code></td><td><code>{ data, error }</code></td><td>회원가입. Auth 계정 생성 + <code>users</code> 테이블에 프로필 row 생성까지 한 번에 처리</td></tr><tr><td><code>signIn</code></td><td><code>{ email, password }</code></td><td><code>{ data, error }</code></td><td>로그인</td></tr><tr><td><code>createDiary</code></td><td><code>{ content }</code></td><td><code>{ data, error }</code></td><td>일기 작성 (글자수 검증 포함)</td></tr><tr><td><code>getDiaries</code></td><td><code>{ authorId }</code></td><td><code>{ data: Diary[], error }</code></td><td>특정 유저의 일기 목록 조회</td></tr><tr><td><code>updateDiary</code></td><td><code>{ id, content }</code></td><td><code>{ data, error }</code></td><td>내가 쓴 일기 수정 (글자수 재검증)</td></tr><tr><td><code>deleteDiary</code></td><td><code>{ id }</code></td><td><code>{ data, error }</code></td><td>내가 쓴 일기 삭제</td></tr><tr><td><code>getFeed</code></td><td><code>{ userId }</code></td><td><code>{ data: Diary[], error }</code></td><td>랜덤 피드 목록</td></tr><tr><td><code>sendZing</code></td><td><code>{ toUserId }</code></td><td><code>{ data, error }</code></td><td>징 보내기</td></tr><tr><td><code>getMatches</code></td><td><code>{ userId }</code></td><td><code>{ data: Match[], error }</code></td><td>매칭 목록</td></tr></tbody></table><p>(실제 구현하면서 계속 추가)</p><h3 id="signup-상세" tabindex="-1"><code>signUp</code> 상세 <a class="header-anchor" href="#signup-상세" aria-label="Permalink to &quot;`signUp` 상세&quot;">​</a></h3><p><strong>파라미터</strong></p><table tabindex="0"><thead><tr><th>필드</th><th>타입</th><th>필수</th><th>설명</th></tr></thead><tbody><tr><td>email</td><td>string</td><td>O</td><td>로그인용 이메일</td></tr><tr><td>password</td><td>string</td><td>O</td><td>비밀번호</td></tr><tr><td>nickname</td><td>string</td><td>O</td><td>화면에 보여줄 이름</td></tr><tr><td>gender</td><td><code>&#39;male&#39;</code> | <code>&#39;female&#39;</code> | <code>null</code></td><td>X</td><td>비공개 선택 시 <code>null</code></td></tr><tr><td>isExchangeStudent</td><td>boolean</td><td>O</td><td>교환학생 여부</td></tr><tr><td>nationality</td><td>string</td><td>O</td><td>국적</td></tr><tr><td>preferredLanguage</td><td>string</td><td>O</td><td>예: <code>&#39;ko&#39;</code>, <code>&#39;en&#39;</code></td></tr></tbody></table><p><strong>리턴</strong></p><table tabindex="0"><thead><tr><th>필드</th><th>타입</th><th>설명</th></tr></thead><tbody><tr><td>data</td><td><code>{ user, session } | null</code></td><td>성공 시 생성된 유저/세션 정보</td></tr><tr><td>error</td><td><code>{ message, status } | null</code></td><td>실패 시 에러 (이메일 중복 등)</td></tr></tbody></table><h3 id="signin-상세" tabindex="-1"><code>signIn</code> 상세 <a class="header-anchor" href="#signin-상세" aria-label="Permalink to &quot;`signIn` 상세&quot;">​</a></h3><p><strong>파라미터</strong></p><table tabindex="0"><thead><tr><th>필드</th><th>타입</th><th>필수</th><th>설명</th></tr></thead><tbody><tr><td>email</td><td>string</td><td>O</td><td></td></tr><tr><td>password</td><td>string</td><td>O</td><td></td></tr></tbody></table><p><strong>리턴</strong></p><table tabindex="0"><thead><tr><th>필드</th><th>타입</th><th>설명</th></tr></thead><tbody><tr><td>data</td><td><code>{ user, session } | null</code></td><td>성공 시 로그인된 유저/세션</td></tr><tr><td>error</td><td><code>{ message, status } | null</code></td><td>실패 시 에러 (비밀번호 틀림 등)</td></tr></tbody></table><h2 id="_4-정책-제약-규칙-미정-항목-—-확정되면-여기-기록" tabindex="-1">4. 정책/제약 규칙 (미정 항목 — 확정되면 여기 기록) <a class="header-anchor" href="#_4-정책-제약-규칙-미정-항목-—-확정되면-여기-기록" aria-label="Permalink to &quot;4. 정책/제약 규칙 (미정 항목 — 확정되면 여기 기록)&quot;">​</a></h2><ul><li>[ ] 동시 매칭 인원 상한</li><li>[ ] 단계적 소통 해금 규칙 (며칠 지속 시 몇 단계, 단계별 허용 행동)</li><li>[ ] 채팅 기능 범위 (하루 메시지 횟수 등)</li><li>[ ] 글감(프롬프트) 기능 도입 여부</li><li>[ ] 단계적 공개 기준 (글자 수 vs 문단 기준)</li></ul>',38)])])}const b=d(o,[["render",i]]);export{g as __pageData,b as default};
